129→// FindEntry search a TreeEntry in this tree or any subtree.
130→func (t *Tree) FindEntry(path string) (*TreeEntry, error) {
131→	if t.t == nil {
132→		t.t = make(map[string]*Tree)
133→	}
134→
135→	pathParts := strings.Split(path, "/")
136→	startingTree := t
137→	pathCurrent := ""
138→
139→	// search for the longest path in the tree path cache
140→	for i := len(pathParts) - 1; i >= 1; i-- {
141→		path := filepath.Join(pathParts[:i]...)
142→
143→		tree, ok := t.t[path]
144→		if ok {
145→			startingTree = tree
146→			pathParts = pathParts[i:]
147→			pathCurrent = path
148→
149→			break
150→		}
151→	}
152→
153→	var tree *Tree
154→	var err error
155→	for tree = startingTree; len(pathParts) > 1; pathParts = pathParts[1:] {
156→		if tree, err = tree.dir(pathParts[0]); err != nil {
157→			return nil, err
158→		}
159→
160→		pathCurrent = filepath.Join(pathCurrent, pathParts[0])
161→		t.t[pathCurrent] = tree
162→	}
163→
164→	return tree.entry(pathParts[0])
165→}
166→
167→func (t *Tree) dir(baseName string) (*Tree, error) {
168→	entry, err := t.entry(baseName)
169→	if err != nil {
170→		return nil, ErrDirectoryNotFound
171→	}
172→
173→	obj, err := t.s.EncodedObject(plumbing.TreeObject, entry.Hash)
174→	if err != nil {
175→		return nil, err
176→	}
177→
178→	tree := &Tree{s: t.s}
179→	err = tree.Decode(obj)
180→
181→	return tree, err
182→}
183→
184→func (t *Tree) entry(baseName string) (*TreeEntry, error) {
185→	if t.m == nil {
186→		t.buildMap()
187→	}
188→
189→	entry, ok := t.m[baseName]
190→	if !ok {
191→		return nil, ErrEntryNotFound
192→	}
193→
194→	return entry, nil
195→}
196→
197→// Files returns a FileIter allowing to iterate over the Tree
198→func (t *Tree) Files() *FileIter {
199→	return NewFileIter(t.s, t)
200→}
201→
202→// ID returns the object ID of the tree. The returned value will always match
203→// the current value of Tree.Hash.
204→//
205→// ID is present to fulfill the Object interface.
206→func (t *Tree) ID() plumbing.Hash {
207→	return t.Hash
208→}
209→
210→// Type returns the type of object. It always returns plumbing.TreeObject.
211→func (t *Tree) Type() plumbing.ObjectType {
212→	return plumbing.TreeObject
213→}
214→
215→// Decode transform an plumbing.EncodedObject into a Tree struct
216→func (t *Tree) Decode(o plumbing.EncodedObject) (err error) {
217→	if o.Type() != plumbing.TreeObject {
218→		return ErrUnsupportedObject
219→	}
220→
221→	t.Hash = o.Hash()
222→	if o.Size() == 0 {
223→		return nil
224→	}
225→
226→	t.Entries = nil
227→	t.m = nil
228→
229→	reader, err := o.Reader()
230→	if err != nil {
231→		return err
232→	}
233→	defer ioutil.CheckClose(reader, &err)
234→
235→	r := sync.GetBufioReader(reader)
236→	defer sync.PutBufioReader(r)
237→
238→	for {
239→		str, err := r.ReadString(' ')
240→		if err != nil {
241→			if err == io.EOF {
242→				break
243→			}
244→
245→			return err
246→		}
247→		str = str[:len(str)-1] // strip last byte (' ')
248→
249→		mode, err := filemode.New(str)
250→		if err != nil {
251→			return err
252→		}
253→
254→		name, err := r.ReadString(0)
255→		if err != nil && err != io.EOF {
256→			return err
257→		}
258→
259→		var hash plumbing.Hash
260→		hash.ResetBySize(t.Hash.Size())
261→		if _, err = hash.ReadFrom(r); err != nil {
262→			return err
263→		}
264→
265→		baseName := name[:len(name)-1]
266→		t.Entries = append(t.Entries, TreeEntry{
267→			Hash: hash,
268→			Mode: mode,
269→			Name: baseName,
270→		})
271→	}
272→
273→	return nil
274→}
275→
276→// TreeEntrySorter is a helper type for sorting TreeEntry slices.
277→type TreeEntrySorter []TreeEntry
278→
279→func (s TreeEntrySorter) Len() int {
280→	return len(s)
281→}
282→
283→func (s TreeEntrySorter) Less(i, j int) bool {
284→	name1 := s[i].Name
285→	name2 := s[j].Name
286→	if s[i].Mode == filemode.Dir {
287→		name1 += "/"
288→	}
289→	if s[j].Mode == filemode.Dir {
290→		name2 += "/"
291→	}
292→	return name1 < name2
293→}
294→
295→func (s TreeEntrySorter) Swap(i, j int) {
296→	s[i], s[j] = s[j], s[i]
297→}
298→
299→// Encode transforms a Tree into a plumbing.EncodedObject.
300→// The tree entries must be sorted by name.
301→func (t *Tree) Encode(o plumbing.EncodedObject) (err error) {
302→	o.SetType(plumbing.TreeObject)
303→	w, err := o.Writer()
304→	if err != nil {
305→		return err
306→	}
307→
308→	defer ioutil.CheckClose(w, &err)
309→
310→	if !sort.IsSorted(TreeEntrySorter(t.Entries)) {
311→		return ErrEntriesNotSorted
312→	}
313→
314→	for _, entry := range t.Entries {
315→		if strings.IndexByte(entry.Name, 0) != -1 {
316→			return fmt.Errorf("malformed filename %q", entry.Name)
317→		}
318→		if _, err = fmt.Fprintf(w, "%o %s", entry.Mode, entry.Name); err != nil {
319→			return err
320→		}
321→
322→		if _, err = w.Write([]byte{0x00}); err != nil {
323→			return err
324→		}
325→
326→		if _, err = entry.Hash.WriteTo(w); err != nil {
327→			return err
328→		}
329→	}
330→
331→	return err
332→}
333→
334→func (t *Tree) buildMap() {
335→	t.m = make(map[string]*TreeEntry)
336→	for i := 0; i < len(t.Entries); i++ {
337→		t.m[t.Entries[i].Name] = &t.Entries[i]
338→	}
339→}
340→
341→// Diff returns a list of changes between this tree and the provided one
342→func (t *Tree) Diff(to *Tree) (Changes, error) {
343→	return t.DiffContext(context.Background(), to)
344→}
345→
346→// DiffContext returns a list of changes between this tree and the provided one
347→// Error will be returned if context expires. Provided context must be non nil.
348→//
349→// NOTE: Since version 5.1.0 the renames are correctly handled, the settings
350→// used are the recommended options DefaultDiffTreeOptions.
351→func (t *Tree) DiffContext(ctx context.Context, to *Tree) (Changes, error) {
352→	return DiffTreeWithOptions(ctx, t, to, DefaultDiffTreeOptions)
353→}
354→
355→// Patch returns a slice of Patch objects with all the changes between trees
356→// in chunks. This representation can be used to create several diff outputs.
357→func (t *Tree) Patch(to *Tree) (*Patch, error) {
358→	return t.PatchContext(context.Background(), to)
359→}
360→
361→// PatchContext returns a slice of Patch objects with all the changes between
362→// trees in chunks. This representation can be used to create several diff
363→// outputs. If context expires, an error will be returned. Provided context must
364→// be non-nil.
365→//
366→// NOTE: Since version 5.1.0 the renames are correctly handled, the settings
367→// used are the recommended options DefaultDiffTreeOptions.
368→func (t *Tree) PatchContext(ctx context.Context, to *Tree) (*Patch, error) {
369→	changes, err := t.DiffContext(ctx, to)
370→	if err != nil {
371→		return nil, err
372→	}
373→
374→	return changes.PatchContext(ctx)
375→}
376→
377→// treeEntryIter facilitates iterating through the TreeEntry objects in a Tree.
378→type treeEntryIter struct {
379→	t   *Tree
380→	pos int
381→}
382→
383→func (iter *treeEntryIter) Next() (TreeEntry, error) {
384→	if iter.pos >= len(iter.t.Entries) {
385→		return TreeEntry{}, io.EOF
386→	}
387→	iter.pos++
388→	return iter.t.Entries[iter.pos-1], nil
389→}
390→
391→// TreeWalker provides a means of walking through all of the entries in a Tree.
392→type TreeWalker struct {
393→	stack     []*treeEntryIter
394→	base      string
395→	recursive bool
396→	seen      map[plumbing.Hash]bool
397→
398→	s storer.EncodedObjectStorer
399→	t *Tree
400→}
401→
402→// NewTreeWalker returns a new TreeWalker for the given tree.
403→//
404→// It is the caller's responsibility to call Close() when finished with the
405→// tree walker.
406→func NewTreeWalker(t *Tree, recursive bool, seen map[plumbing.Hash]bool) *TreeWalker {
407→	stack := make([]*treeEntryIter, 0, startingStackSize)
408→	stack = append(stack, &treeEntryIter{t, 0})
409→
410→	return &TreeWalker{
411→		stack:     stack,
412→		recursive: recursive,
413→		seen:      seen,
414→
415→		s: t.s,
416→		t: t,
417→	}
418→}
419→
420→// Next returns the next object from the tree. Objects are returned in order
421→// and subtrees are included. After the last object has been returned further
422→// calls to Next() will return io.EOF.
423→//
424→// In the current implementation any objects which cannot be found in the
425→// underlying repository will be skipped automatically. It is possible that this
426→// may change in future versions.
427→func (w *TreeWalker) Next() (name string, entry TreeEntry, err error) {
428→	var obj *Tree
429→	for {
430→		current := len(w.stack) - 1
431→		if current < 0 {
432→			// Nothing left on the stack so we're finished
433→			err = io.EOF
434→			return name, entry, err
435→		}
436→
437→		if current > maxTreeDepth {
438→			// We're probably following bad data or some self-referencing tree
439→			err = ErrMaxTreeDepth
440→			return name, entry, err
441→		}
442→
443→		entry, err = w.stack[current].Next()
444→		if err == io.EOF {
445→			// Finished with the current tree, move back up to the parent
446→			w.stack = w.stack[:current]
447→			w.base, _ = path.Split(w.base)
448→			w.base = strings.TrimSuffix(w.base, "/")
449→			continue
450→		}
451→
452→		if err != nil {
453→			return name, entry, err
454→		}
455→
456→		if w.seen[entry.Hash] {
457→			continue
458→		}
459→
460→		if entry.Mode == filemode.Dir {
461→			obj, err = GetTree(w.s, entry.Hash)
462→		}
463→
464→		name = simpleJoin(w.base, entry.Name)
465→
466→		if err != nil {
467→			err = io.EOF
468→			return name, entry, err
469→		}
470→
471→		break
472→	}
473→
474→	if !w.recursive {
475→		return name, entry, err
476→	}
477→
478→	if obj != nil {
479→		w.stack = append(w.stack, &treeEntryIter{obj, 0})
480→		w.base = simpleJoin(w.base, entry.Name)
481→	}
482→
483→	return name, entry, err
484→}
485→
486→// Tree returns the tree that the tree walker most recently operated on.
487→func (w *TreeWalker) Tree() *Tree {
488→	current := len(w.stack) - 1
489→	if w.stack[current].pos == 0 {
490→		current--
491→	}
492→
493→	if current < 0 {
494→		return nil
495→	}
496→
497→	return w.stack[current].t
498→}
499→
500→// Close releases any resources used by the TreeWalker.
501→func (w *TreeWalker) Close() {
502→	w.stack = nil
503→}
504→
505→// TreeIter provides an iterator for a set of trees.
506→type TreeIter struct {
507→	storer.EncodedObjectIter
508→	s storer.EncodedObjectStorer
509→}
510→
511→// NewTreeIter takes a storer.EncodedObjectStorer and a
512→// storer.EncodedObjectIter and returns a *TreeIter that iterates over all
513→// tree contained in the storer.EncodedObjectIter.
514→//
515→// Any non-tree object returned by the storer.EncodedObjectIter is skipped.
516→func NewTreeIter(s storer.EncodedObjectStorer, iter storer.EncodedObjectIter) *TreeIter {
517→	return &TreeIter{iter, s}
518→}
519→
520→// Next moves the iterator to the next tree and returns a pointer to it. If
521→// there are no more trees, it returns io.EOF.
522→func (iter *TreeIter) Next() (*Tree, error) {
523→	for {
524→		obj, err := iter.EncodedObjectIter.Next()
525→		if err != nil {
526→			return nil, err
527→		}
528→
529→		if obj.Type() != plumbing.TreeObject {
530→			continue
531→		}
532→
533→		return DecodeTree(iter.s, obj)
534→	}
535→}
536→
537→// ForEach call the cb function for each tree contained on this iter until
538→// an error happens or the end of the iter is reached. If ErrStop is sent
539→// the iteration is stop but no error is returned. The iterator is closed.
540→func (iter *TreeIter) ForEach(cb func(*Tree) error) error {
541→	return iter.EncodedObjectIter.ForEach(func(obj plumbing.EncodedObject) error {
542→		if obj.Type() != plumbing.TreeObject {
543→			return nil
544→		}
545→
546→		t, err := DecodeTree(iter.s, obj)
547→		if err != nil {
548→			return err
549→		}
550→
551→		return cb(t)
552→	})
553→}
554→
555→func simpleJoin(parent, child string) string {
556→	if len(parent) > 0 {
557→		return parent + "/" + child
558→	}
559→	return child
560→}
