 21→// GetBlob gets a blob from an object storer and decodes it.
 22→func GetBlob(s storer.EncodedObjectStorer, h plumbing.Hash) (*Blob, error) {
 23→	o, err := s.EncodedObject(plumbing.BlobObject, h)
 24→	if err != nil {
 25→		return nil, err
